using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using PiperPlus.Core.Inference;

namespace PiperPlus.Core.Tests;

/// <summary>
/// Kaldi fbank + kaiser_best resample parity with torchaudio.
/// </summary>
/// <remarks>
/// Reads <c>test/fixtures/kaldi_fbank_golden.json</c> (generated by
/// <c>test/generate_kaldi_fbank_golden.py</c> with torchaudio, shared with the
/// browser's <c>test-kaldi-fbank-golden.js</c>) and checks the front end used for
/// the public zs-v1 base's CAM++ embeddings. torchaudio computes in float32 and
/// this port in double, so values are compared with an absolute tolerance.
/// </remarks>
public class KaldiFbankTests
{
    // Tolerances cover float32 rounding in torchaudio, not algorithm changes
    // (same values as test-kaldi-fbank-golden.js): the largest fbank
    // differences sit in bins whose log energy is near -16, where float32 FFT
    // cancellation dominates; a wrong window, mel scale or preemphasis moves
    // whole frames by far more than 1e-2.
    private const double ResampleMaxAbs = 5e-5;
    private const double FbankMaxAbs = 1e-2;
    private const double FbankMeanAbs = 1e-3;

    internal static JsonElement LoadFixture(string name)
    {
        DirectoryInfo? d = new(AppContext.BaseDirectory);
        while (d is not null && !File.Exists(Path.Join(d.FullName, "test", "fixtures", name)))
        {
            d = d.Parent;
        }

        Assert.NotNull(d);
        using JsonDocument doc = JsonDocument.Parse(File.ReadAllText(Path.Join(d.FullName, "test", "fixtures", name)));
        return doc.RootElement.Clone();
    }

    internal static float[] Floats(JsonElement array) =>
        array.EnumerateArray().Select(v => v.GetSingle()).ToArray();

    // Mirrors test_signal() in the generator: DC offset plus sines below
    // Nyquist, computed in double and stored as float.
    private static float[] TestSignal(JsonElement fixture, int sampleRate, double seconds)
    {
        JsonElement signal = fixture.GetProperty("signal");
        double dc = signal.GetProperty("dc_offset").GetDouble();
        double[][] partials = signal.GetProperty("partials").EnumerateArray()
            .Select(p => p.EnumerateArray().Select(v => v.GetDouble()).ToArray())
            .ToArray();
        int n = (int)Math.Round(sampleRate * seconds);
        float[] output = new float[n];
        for (int i = 0; i < n; i++)
        {
            double x = dc;
            foreach (double[] p in partials.Where(q => q[1] < sampleRate / 2.0))
            {
                x += p[0] * Math.Sin((2 * Math.PI * p[1] * i / sampleRate) + p[2]);
            }

            output[i] = (float)x;
        }

        return output;
    }

    private static (double Max, double Mean) AbsDiffs(float[] actual, float[] expected)
    {
        Assert.Equal(expected.Length, actual.Length);
        double max = 0;
        double sum = 0;
        for (int i = 0; i < actual.Length; i++)
        {
            double d = Math.Abs(actual[i] - expected[i]);
            max = Math.Max(max, d);
            sum += d;
        }

        return (max, sum / actual.Length);
    }

    private static void AssertFbankClose(float[] feats, JsonElement c)
    {
        Assert.Equal(c.GetProperty("frames").GetInt32(), feats.Length / KaldiFbank.NumMelBins);
        (double max, double mean) = AbsDiffs(feats, Floats(c.GetProperty("values")));
        Assert.True(max < FbankMaxAbs, $"max abs diff {max}");
        Assert.True(mean < FbankMeanAbs, $"mean abs diff {mean}");
    }

    [Fact]
    public void ResampleKaiserBest_MatchesTorchaudio()
    {
        JsonElement fixture = LoadFixture("kaldi_fbank_golden.json");
        JsonElement[] cases = fixture.GetProperty("resample_cases").EnumerateArray().ToArray();
        Assert.NotEmpty(cases);
        foreach (JsonElement c in cases)
        {
            int rate = c.GetProperty("input_rate").GetInt32();
            float[] output = KaldiFbank.ResampleKaiserBest(
                TestSignal(fixture, rate, c.GetProperty("seconds").GetDouble()), rate, 16000);
            (double max, _) = AbsDiffs(output, Floats(c.GetProperty("output")));
            Assert.True(max < ResampleMaxAbs, $"{rate} Hz -> 16000 Hz: max abs diff {max}");
        }
    }

    [Fact]
    public void ResampleKaiserBest_SameRateReturnsInputAndRejectsBadRates()
    {
        float[] x = [0.1f, -0.2f, 0.3f];
        Assert.Same(x, KaldiFbank.ResampleKaiserBest(x, 16000, 16000));
        Assert.Throws<ArgumentOutOfRangeException>(() => KaldiFbank.ResampleKaiserBest(x, 0, 16000));
    }

    [Fact]
    public void Fbank_MatchesTorchaudioOn16kSignal()
    {
        JsonElement fixture = LoadFixture("kaldi_fbank_golden.json");
        JsonElement c = fixture.GetProperty("fbank_case");
        float[] input = TestSignal(fixture, c.GetProperty("input_rate").GetInt32(), c.GetProperty("seconds").GetDouble());
        AssertFbankClose(KaldiFbank.Fbank(input), c);
    }

    [Fact]
    public void Fbank_MatchesTorchaudioAfterResampling()
    {
        JsonElement fixture = LoadFixture("kaldi_fbank_golden.json");
        JsonElement c = fixture.GetProperty("pipeline_case");
        int rate = c.GetProperty("input_rate").GetInt32();
        float[] resampled = KaldiFbank.ResampleKaiserBest(
            TestSignal(fixture, rate, c.GetProperty("seconds").GetDouble()), rate, 16000);
        AssertFbankClose(KaldiFbank.Fbank(resampled), c);
    }

    [Fact]
    public void Fbank_NeedsOneFullWindow()
    {
        Assert.Empty(KaldiFbank.Fbank(new float[399]));
        Assert.Equal(KaldiFbank.NumMelBins, KaldiFbank.Fbank(new float[400]).Length);
    }

    [Fact]
    public void SubtractBandMeans_ZeroesEachBinMean()
    {
        float[] feats = Enumerable.Range(0, 3 * KaldiFbank.NumMelBins).Select(i => (float)i).ToArray();
        KaldiFbank.SubtractBandMeans(feats);
        for (int m = 0; m < KaldiFbank.NumMelBins; m++)
        {
            double sum = 0;
            for (int f = 0; f < 3; f++)
            {
                sum += feats[(f * KaldiFbank.NumMelBins) + m];
            }

            Assert.True(Math.Abs(sum) < 1e-3, $"bin {m} mean {sum}");
        }
    }

    [Theory]
    [InlineData(192, SpeakerFrontEnd.KaldiFbank)]
    [InlineData(256, SpeakerFrontEnd.Mel)]
    [InlineData(0, SpeakerFrontEnd.Mel)]
    public void FrontEnd_FollowsEmbeddingDim(int dim, SpeakerFrontEnd expected)
    {
        Assert.Equal(expected, SpeakerEncoder.ForEmbeddingDim(dim));
    }

    [Fact]
    public void L2Normalize_ScalesToUnitNormAndRejectsDegenerateVectors()
    {
        float[] output = SpeakerEncoder.L2Normalize([3f, 4f]);
        Assert.Equal(0.6f, output[0], 1e-6f);
        Assert.Equal(0.8f, output[1], 1e-6f);
        Assert.Throws<InvalidOperationException>(() => SpeakerEncoder.L2Normalize([0f, 0f]));
        Assert.Throws<InvalidOperationException>(() => SpeakerEncoder.L2Normalize([float.NaN, 1f]));
    }
}
